+            url::Host::Domain(domain) => PeerAddr(io_result(
+                (domain, port).to_socket_addrs()?.nth(0),
+                "Could not resolve domain",
+            )?),
+            url::Host::Ipv4(ip) => PeerAddr((ip, port).into()),
+            url::Host::Ipv6(ip) => PeerAddr((ip, port).into()),
+        })
+    }
