+    let mut main_sel2 = Query::select();
+    main_sel2
+        .expr(Expr::col(Asterisk))
+        .from(TableRef::Table(sub_select2_name));
+    let mut main_sel1 = Query::select();
+    main_sel1
+        .expr(Expr::col(Asterisk))
