+                            stdout: output.stdout,
+                            stderr: output.stderr,
+                            build_target_error: Box::new(build_target_error),
+                        })
+                    }
+                }
+            }
+        }
+        Err(error) => {
+            match build_target {
+                Ok(build_target) => {
