+
+  const episodeMetrics = Object.entries(metrics)
+    .filter(([, metric]) => {
+      try {
+        return getInferenceJoinKey(metric) === InferenceJoinKey.EPISODE_ID;
+      } catch {
+        return false;
+      }
+    })
+    .map(([name]) => name);
